// ביטול סט שסומן בטעות (26.10.26): מנקה את הרישום האחרון של היום לאותו תרגיל, משקל וחזרות, ומחזיר את ההיסטוריה המעודכנת
function appLiftDel_(t, b) { const name = appNameByToken_(t); if (!name) throw new Error('הקישור לא בתוקף');
  const c = clientRow(name), ws = appLiftSheet_(c); if (!ws) throw new Error('אין לשונית משקלי עבודה בקובץ המעקב');
  const nx = s => String(s || '').trim().replace(/\s*\([^()]*\)\s*$/, ''), ex = nx(b.ex), kg = Math.round(Number(String(b.kg).replace(',', '.')) * 4) / 4, reps = Math.round(Number(b.reps)), today = startOfDay(new Date()).getTime();
  const n = Math.max(204, ws.getLastRow()), vals = ws.getRange(5, 1, n - 4, 5).getValues();
  for (let k = vals.length - 1; k >= 0; k--) { const r = vals[k]; if (r[0] instanceof Date && startOfDay(r[0]).getTime() === today && nx(r[2]) === ex && Math.abs(Number(r[3]) - kg) < 0.01 && Number(r[4]) === reps) {
    ws.getRange(5 + k, 1, 1, Math.min(6, Math.max(5, ws.getLastColumn()))).clearContent(); SpreadsheetApp.flush(); return appLifts_(c); } }
  throw new Error('לא מצאתי את הסט הזה ברישומים של היום'); }
